/**
 * Calculate the arithmetic mean of a sequence of numbers.
 * 
 * @param values Array of numbers to calculate the mean
 * @returns The mean value
 * 
 * @example
 * ```ts
 * import { math } from 'lambda-toolkit';
 * const { calcMean } = math;
 * 
 * const result = calcMean([1, 2, 3, 4]);
 * // result: 2.5
 * ```
 */
export function calcMean(values: number[]): number;
